    // Physics Logic (Deterministic Sub-stepping)
    const SUB_STEPS = 10; // Steps per simulation tick

    // Main physics update called by step(dt)
    let lastStepTime = performance.now();

    function updatePhysics(dt) {
        // dt is in seconds. Convert to milliseconds for easier calc? Or keep units consistent.
        const subDt = dt / SUB_STEPS; 
        const frictionCoeff = 0.985; // Percentage of velocity kept per second (exponential decay approximates linear friction at low speeds)

        // We need a way to stop balls completely when very slow, but deterministically.
        // Use a threshold speed below which v=0.

        const stepTime = subDt * 1000; // ms

