                if (Math.abs(b.vx) < 0.05) b.vx = 0;
                if (Math.abs(b.vy) < 0.05) b.vy = 0;

                // Integrate position
                b.x += b.vx * subDt;
                b.y += b.vy * subDt;

                // Wall Collisions / Bounds
                let collidedX = false, collidedY = false;

                // Left Rail (x < R) -> reflect X and clamp x to R. 
                if (b.x - R < 0) {
                    b.vx *= RESTITUTION;
                    b.x = R + Math.abs(b.x - R); // Clamp out of wall
                    collidedX = true;
                } else if (b.x + R > W) {
                    b.vx *= RESTITUTION;
                    b.x = W - R - Math.abs(b.x - (W-R));
                    collidedX = true;
                }

                // Top Rail (y < R) -> reflect Y and clamp y to R.
                if (b.y - R < 0) {
                    b.vy *= RESTITUTION;
                    b.y = R + Math.abs(b.y - R);
                    collidedY = true;
                } else if (b.y + R > H) {
                    b.vy *= RESTITUTION;
                    b.y = H - R - Math.abs(b.y - (H-R));
                    collidedY = true;
                }

                // Pocket Check: Only check on collision with rails or initial state? 
