                        // "potted... out of play". Keep in array, set potted=true. Velocity should be zero.
                        b.potted = true;
                        b.vx = 0;
                        b.vy = 0;
                    }
                }

            }

            // Ball-Ball Collisions (Iterative resolution to prevent stacking/sticking)
            for(let i=0; i<balls.length; i++) {
                let A = balls[i];
                if(A.potted) continue;

                for(let j=i+1; j<balls.length; j++) {
                    let B = balls[j];
                    if(B.potted) continue;

                    const dx = B.x - A.x;
                    const dy = B.y - A.y;
                    const distSq = dx*dx + dy*dy;
                    const minDist = R * 2; // Sum of radii

                    if (distSq < minDist * minDist) {
                        // Collision detected! Resolve overlap and velocity.

                        // Normal vector
                        let nx, ny;
                        if(distSq === 0) {
                            // Overlapping exactly, pick arbitrary normal to prevent glitching
                            nx = 1; ny = 0; 
                        } else {
                            const d = Math.sqrt(distSq);
                            nx = dx / d;
                            ny = dy / d;
                        }

                        // Positional Correction: Push balls apart to avoid sticking.
                        const overlap = minDist - Math.sqrt(distSq);
                        if(overlap > 0) {
                             // Move each ball half the overlap along normal (opposite for B, same for A? No.)
                             // To conserve momentum during correction, move proportional to mass inverse (masses equal -> split).
                             const push = overlap / 2;
                             A.x -= nx * push;
                             A.y -= ny * push;
                             B.x += nx * push;
                             B.y += ny * push;
                        }

                        // Velocity Resolution: Impulse along normal.
                        // Relative velocity vector V_rel = (A.vx, A.vy) - (B.vx, B.vy).
                        const rx = A.vx - B.vx;
                        const ry = A.vy - B.vy;

                        // Dot product relative vel with normal
                        const relVelAlongNormal = rx * nx + ry * ny;

                        // If moving apart, do nothing. 
                        if (relVelAlongNormal > 0) continue; 

                        // Calculate impulse magnitude for elastic collision
                        // j = -(1+e) * Vn / (1/mA + 1/mB) -> For equal mass: j = -Vn / 2
                        let jVal = (- (1 + RESTITUTION) * relVelAlongNormal) / 2;

                        const impulseX = jVal * nx;
                        const impulseY = jVal * ny;

                        A.vx += impulseX;
                        A.vy += impulseY;
                        B.vx -= impulseX;
                        B.vy -= impulseY;
                    }
                }
            } // End Ball Loop

        } // End Sub-Step Loop

        moved = true; // Logic updated, redraw needed.
    };

