            // Ball-Ball Collisions (Iterative resolution)
            for(let i=0; i<balls.length; i++) {
                let A = balls[i];
                if(A.potted) continue;

                for(let j=i+1; j<balls.length; j++) {
                    let B = balls[j];
                    if(B.potted) continue;

                    const dx = B.x - A.x;
                    const dy = B.y - A.y;
                    const distSq = dx*dx + dy*dy;

                    if (distSq < 4 * R * R) { // Overlap

                        let nx, ny;
                        if(distSq === 0) {
                            nx = 1; ny = 0; 
                        } else {
                            const d = Math.sqrt(distSq);
                            nx = dx / d;
                            ny = dy / d;
                        }

                        // Positional Correction (push apart to avoid sticking)
                        const overlap = (2 * R) - Math.sqrt(distSq);
                        if(overlap > 0) {
                             A.x -= nx * overlap/2;
                             A.y -= ny * overlap/2;
                             B.x += nx * overlap/2;
                             B.y += ny * overlap/2;
                        }

                        // Velocity Resolution (Elastic Collision)
                        const rx = A.vx - B.vx;
                        const ry = A.vy - B.vy;

                        const relVelAlongNormal = rx * nx + ry * ny;

                        if (relVelAlongNormal > 0) continue; 

                        // For equal mass, impulse magnitude j = -(1+e)*Vn / 2
                        let jVal = (- (1 + RESTITUTION) * relVelAlongNormal) / 2;

                        const impulseX = jVal * nx;
                        const impulseY = jVal * ny;

                        A.vx += impulseX;
                        A.vy += impulseY;
                        B.vx -= impulseX;
                        B.vy -= impulseY;
                    } // End Overlap check
                } 
            } 

        } // End Sub-Step Loop

